// Do not edit. Run `bun scripts/mirror-import.ts --sync-from-app <appRoot>`.

// Third-party tracking providers. Pure (no convex/react imports) so it's shared
// by the settings UI, onboarding, the consent gate, the scraper, the privacy
// policy generator, and Convex. The Convex validator that mirrors this lives in
// convex/model/tracking.ts and MUST keep the same keys.
//
// Safety: we only ever store a *validated id* (matched against a strict pattern)
// and later interpolate it into a known, provider-specific snippet. Arbitrary
// user-supplied script is never accepted - this preserves the "no raw HTML"
// model of the rest of the builder.

export const TRACKING_PROVIDERS = [
  "ga4",
  "gtm",
  "metaPixel",
  "linkedin",
  "hubspot",
  "hotjar",
] as const;

export type TrackingProvider = (typeof TRACKING_PROVIDERS)[number];

/** A site's tracking configuration: a validated id per enabled provider. */
export type TrackingConfig = Partial<Record<TrackingProvider, string | undefined>>;

/** Consent buckets. "necessary" needs no consent and is never gated. */
export type ConsentCategory = "analytics" | "marketing";

type Localized = { sv: string; en: string; pl: string };

export type TrackingMeta = {
  label: string;
  /** Which consent bucket(s) this tool falls under. GTM spans both because a
   *  container can load either kind of tag. */
  categories: ConsentCategory[];
  /** Strict id format for manual entry (anchored). */
  pattern: RegExp;
  /** Normalize a matched id to its canonical stored form. */
  normalize: (id: string) => string;
  placeholder: string;
  /** Where to find this id (linked from the picker). */
  helpUrl: string;
  /** Cookies / storage keys this tool sets - disclosed in the privacy policy. */
  cookieNames: string[];
  /** Plain-language outcome shown in the goal picker. */
  outcome: Localized;
  /** What it does - used by the privacy policy generator. */
  purpose: Localized;
};

const upper = (id: string) => id.toUpperCase();
const identity = (id: string) => id;

