// Unanchored signatures for sniffing an id out of an existing site's HTML (or a
// pasted snippet). Group 1 is the id when present, otherwise the whole match.
const DETECT: Record<TrackingProvider, RegExp[]> = {
  gtm: [/GTM-[A-Z0-9]{4,}/i],
  ga4: [/\bG-[A-Z0-9]{4,}\b/i],
  metaPixel: [
    /fbq\(\s*['"]init['"]\s*,\s*['"](\d{6,20})['"]/i,
    /facebook\.com\/tr\?id=(\d{6,20})/i,
  ],
  linkedin: [
    /_linkedin_partner_id\s*=\s*["']?(\d{3,12})/i,
    /linkedin_data_partner_ids\.push\(\s*["']?(\d{3,12})/i,
  ],
  hubspot: [
    /js\.hs-scripts\.com\/(\d{3,12})/i,
    /js\.hs-analytics\.net\/analytics\/[^/]+\/(\d{3,12})/i,
  ],
  hotjar: [
    /hjid\s*:\s*(\d{3,12})/i,
    /static\.hotjar\.com\/c\/hotjar-(\d{3,12})/i,
  ],
};

/** Detect configured tracking tools by scanning raw HTML (or a pasted snippet).
 *  Used by the "import from existing site" flow. Best-effort. */
export function detectTrackingFromHtml(html: string): TrackingConfig {
  const found: TrackingConfig = {};
  if (typeof html !== "string" || !html) return found;
  for (const provider of TRACKING_PROVIDERS) {
    for (const re of DETECT[provider]) {
      const m = html.match(re);
      if (m) {
        const id = (m[1] ?? m[0]).trim();
        found[provider] = TRACKING_META[provider].normalize(id);
        break;
      }
    }
  }
  return found;
}

/** Validate + normalize a single id. Returns the canonical id or null.
 *  Forgiving: if the value isn't a bare id we try to sniff one out of it (so a
 *  user can paste a whole snippet). The output is always a constrained id. */
export function validateTrackingId(
  provider: TrackingProvider,
  raw: unknown,
): string | null {
  if (typeof raw !== "string") return null;
  const trimmed = raw.trim();
  if (!trimmed) return null;
  const meta = TRACKING_META[provider];
  if (meta.pattern.test(trimmed)) return meta.normalize(trimmed);
  const sniffed = detectTrackingFromHtml(trimmed)[provider];
  return sniffed ?? null;
}

/** Validate a whole config, dropping any invalid/empty entries. */
export function sanitizeTracking(input: TrackingConfig | undefined): TrackingConfig {
  const out: TrackingConfig = {};
  if (!input) return out;
  for (const provider of TRACKING_PROVIDERS) {
    const id = validateTrackingId(provider, input[provider]);
    if (id) out[provider] = id;
  }
  return out;
}

/** Providers configured, in stable display order. */
export function enabledProviders(tracking: TrackingConfig | undefined): TrackingProvider[] {
  if (!tracking) return [];
  return TRACKING_PROVIDERS.filter((p) => !!tracking[p]);
}

export function hasAnyTracking(tracking: TrackingConfig | undefined): boolean {
  return enabledProviders(tracking).length > 0;
}

/** Which consent categories are actually in play given the configured tools. */
export function usedCategories(
  tracking: TrackingConfig | undefined,
): Record<ConsentCategory, boolean> {
  const used: Record<ConsentCategory, boolean> = { analytics: false, marketing: false };
  for (const p of enabledProviders(tracking)) {
    for (const c of TRACKING_META[p].categories) used[c] = true;
  }
  return used;
}
